#!/usr/bin/env python3
"""Exercise the actual retained UI-main observer with kernel API fixtures."""
from pathlib import Path
import argparse,hashlib,json,subprocess
p=argparse.ArgumentParser(description=__doc__)
p.add_argument('--device',type=Path,required=True);p.add_argument('--out',type=Path,required=True);p.add_argument('--cc',default='clang')
a=p.parse_args();a.out.mkdir(parents=True,exist_ok=False)
source=a.device/'package/BootUiTraceProbe.c';text=source.read_text()
begin=text.index('struct bt_ui_target {');end=text.index('\nvoid boot_ui_trace_task',begin)
actual=text[begin:end]
prefix='\n#include <stdint.h>\n#include <stdio.h>\n#include <string.h>\n#include <stdbool.h>\n#include <assert.h>\n#include <stdarg.h>\n#include <stdlib.h>\n#define KERN_SUCCESS 0\n#define ARM_THREAD_STATE64 6\n#define ARM_THREAD_STATE64_COUNT 68\n#define THREAD_NULL NULL\n#define TH_TERMINATE 4u\n#define TH_TERMINATE2 8u\n#define BT_STRIP_USER_PC(v) ((v)&0x7fffffffffffULL)\ntypedef int kern_return_t;typedef unsigned mach_msg_type_number_t;typedef unsigned *thread_state_t;\ntypedef struct {uint64_t x[29],fp,lr,sp,pc;unsigned cpsr,flags;} arm_thread_state64_t;\nstruct Thread {unsigned refs,state,block_hint;int sched_pri,sched_lock;uint64_t thread_id,wait_event,cpu;};\ntypedef struct Thread *thread_t;\nstruct Map {unsigned refs;};typedef struct Map *vm_map_t;\nstruct Space {unsigned refs;};typedef struct Space *ipc_space_t;\nstruct Task {struct {thread_t first;} threads;vm_map_t map;ipc_space_t itk_space;unsigned task_shared_region_slide;bool locked,busy;};\ntypedef struct Task *task_t;\n#define queue_iterate(q,v,t,l) for(v=(q)->first;v;v=NULL)\nstatic bool irq=true;static unsigned taskLocks,schedLocks,readCalls,stateCalls,printed,declared_pid,declared_slot,first_seq,matching,errors;\nstatic unsigned config=1;static uint64_t tick=1000000000;\nstatic bool readFailure,changed,stateFailure;static int thread_lck_grp;\nstatic bool task_lock_try(task_t t){if(t->busy)return false;assert(!t->locked);t->locked=true;++taskLocks;return true;}\nstatic void task_unlock(task_t t){assert(t->locked&&taskLocks);t->locked=false;--taskLocks;}\nstatic void thread_reference(thread_t t){assert(taskLocks);++t->refs;}\nstatic void thread_deallocate(thread_t t){assert(!taskLocks&&!schedLocks&&t->refs);--t->refs;}\nstatic void vm_map_reference(vm_map_t m){assert(taskLocks);++m->refs;}\nstatic void vm_map_deallocate(vm_map_t m){assert(!taskLocks&&!schedLocks&&m->refs);--m->refs;}\nstatic void is_reference(ipc_space_t s){assert(taskLocks);++s->refs;}\nstatic void is_release(ipc_space_t s){assert(!taskLocks&&!schedLocks&&s->refs);--s->refs;}\nstatic bool ml_get_interrupts_enabled(void){return irq;}\nstatic bool ml_set_interrupts_enabled(bool enabled){bool old=irq;irq=enabled;return old;}\nstatic bool simple_lock_try(int *lock,int *group){(void)group;assert(!irq);if(*lock)return false;*lock=1;++schedLocks;return true;}\nstatic void thread_unlock(thread_t t){assert(!irq&&t->sched_lock&&schedLocks);t->sched_lock=0;--schedLocks;}\nstatic uint64_t recount_thread_time_mach(thread_t t){assert(schedLocks&&!irq);return t->cpu;}\nstatic uint64_t mach_absolute_time(void){return ++tick;}\nstatic void absolutetime_to_nanoseconds(uint64_t t,uint64_t *out){*out=t;}\nstatic bool PE_parse_boot_argn(const char *name,unsigned *out,unsigned bytes){assert(!strcmp(name,"ndt")&&bytes==4);*out=config;return true;}\nstatic int thread_get_state(thread_t t,int flavor,thread_state_t out,mach_msg_type_number_t *count){\n assert(irq&&!schedLocks&&!taskLocks&&t->refs);assert(flavor==6&&*count==68);++stateCalls;\n if(stateFailure)return 5;\n arm_thread_state64_t *state=(void *)out;state->pc=0x100100;state->lr=0x100200;state->fp=0x10000;state->sp=0xff00;\n if(changed&&!(stateCalls%2))state->pc+=4;state->x[16]=UINT64_MAX-46;state->x[1]=1;state->x[3]=42;*count=68;return 0;\n}\nstatic int capture_printf(const char *format,...){\n assert(irq&&!schedLocks&&!taskLocks);va_list ap;va_start(ap,format);char text[1024];vsnprintf(text,sizeof text,format,ap);va_end(ap);++printed;\n if(!strncmp(text,"NEZHA UI MAIN:",14)){int pid,peer,peer_error,kr,rekr,priority;unsigned st,hint,same,err,missed;\n unsigned long long seq,tid,t0,tq,t1,cpu,wait,pc,lr,fp,sp;\n assert(sscanf(text,"NEZHA UI MAIN: pid=%d seq=%llu tid=%llu t0=%llu tq=%llu t1=%llu cpu=%llu st=%x pri=%d hint=%u wait=%llx pc=%llx lr=%llx fp=%llx sp=%llx same=%u err=%u peer=%d/%u missed=%u kr=%d/%d",&pid,&seq,&tid,&t0,&tq,&t1,&cpu,&st,&priority,&hint,&wait,&pc,&lr,&fp,&sp,&same,&err,&peer,&peer_error,&missed,&kr,&rekr)==22);\n assert(t0<=tq&&tq<=t1&&tid&&cpu);declared_pid=pid;first_seq=(unsigned)seq;matching=same;errors=err;\n }\n return 0;\n}\n#define printf capture_printf\n#include "BootUiTraceCore.h"\nstatic int read_user(void *context,uint64_t at,void *out,unsigned bytes){\n vm_map_t map=context;assert(irq&&!taskLocks&&!schedLocks&&map->refs&&at==0x10000&&bytes==16);++readCalls;\n if(readFailure)return 1;uint64_t pair[2]={0,0x100300};memcpy(out,pair,16);return 0;\n}\nstatic void lookup_peer(struct bt_entry *entry,ipc_space_t space){assert(irq&&!taskLocks&&!schedLocks&&space->refs);entry->peer=99;entry->peer_code=0;}\n'
main='\nint main(void){unsigned cases=0;\n struct Thread one={.thread_id=10,.cpu=1234},two={.thread_id=20,.cpu=9876};\n struct Map map={0};struct Space space={0};struct Task task={.threads.first=&one,.map=&map,.itk_space=&space,.task_shared_region_slide=123};\n boot_ui_trace_main_target(&task,100,"Other");assert(!boot_ui_trace_main_active()&&!one.refs);++cases;\n task.busy=true;boot_ui_trace_main_target(&task,100,"Preferences");assert(!one.refs);task.busy=false;++cases;\n boot_ui_trace_main_target(&task,100,"Preferences");assert(one.refs==1&&map.refs==1&&space.refs==1&&boot_ui_trace_main_active());++cases;\n boot_ui_trace_main_target(&task,100,"Preferences");assert(one.refs==1&&map.refs==1);++cases;\n boot_ui_trace_main_sample();assert(stateCalls==2&&readCalls==1&&declared_pid==100&&first_seq==1&&matching&&!errors);++cases;\n changed=true;boot_ui_trace_main_sample();assert(!matching);changed=false;++cases;\n readFailure=true;boot_ui_trace_main_sample();assert(errors==1);readFailure=false;++cases;\n stateFailure=true;unsigned readBefore=readCalls;boot_ui_trace_main_sample();assert(errors==4&&readCalls==readBefore);stateFailure=false;++cases;\n one.sched_lock=1;unsigned count=stateCalls;boot_ui_trace_main_sample();assert(stateCalls==count&&ui_main_targets[0].missed==1);one.sched_lock=0;++cases;\n task.threads.first=&two;boot_ui_trace_main_target(&task,101,"Preferences");assert(!one.refs&&two.refs==1&&map.refs==1&&space.refs==1);++cases;\n two.state=TH_TERMINATE;boot_ui_trace_main_sample();assert(!two.refs&&!map.refs&&!space.refs&&!boot_ui_trace_main_active());two.state=0;++cases;\n task.threads.first=&one;boot_ui_trace_main_target(&task,102,"Calculator");assert(one.refs==1&&ui_main_targets[1].thread==&one);++cases;\n tick+=1800000000000ULL;boot_ui_trace_main_sample();assert(!one.refs&&!map.refs&&!space.refs&&ui_main_enabled==2);++cases;\n boot_ui_trace_main_target(&task,104,"Preferences");assert(!one.refs&&!boot_ui_trace_main_active());++cases;\n assert(!taskLocks&&!schedLocks&&irq);fprintf(stdout,"PASS %u actual UI main target/sampler lifetime cases; lock-free reads, CPU clocks, main replacement and termination\\n",cases);\n}\n'
cpp=a.out/'actual.c';cpp.write_text(prefix+actual+main)
command=[a.cc,'-std=c11','-O1','-g','-Wall','-Wextra','-Werror','-Wno-unused-function','-Wno-unused-variable','-fsanitize=address,undefined','-fno-sanitize-recover=all','-I',str(a.device/'package'),str(cpp),'-o',str(a.out/'actual')]
built=subprocess.run(command,capture_output=True,text=True,timeout=60);(a.out/'build.log').write_text(built.stdout+built.stderr)
assert built.returncode==0,built.stderr
run=subprocess.run([str(a.out/'actual')],capture_output=True,text=True,timeout=30);(a.out/'run.log').write_text(run.stdout+run.stderr)
assert run.returncode==0 and 'PASS 14 actual UI main target/sampler' in run.stdout,run.stdout+run.stderr
report=dict(passed=True,cases=14,actual_production_sampler_target_executed=True,ASan_UBSan=True,retained_thread_map_space_balanced_after_exit=True,reads_assert_no_task_or_scheduler_lock=True,sample_errors_and_rechecks=True,kernel_API_supplied_by_fixture=True,kernel_target_pending=True,source_SHA256=hashlib.sha256(source.read_bytes()).hexdigest(),command=command,phone_operations=False)
(a.out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
